"""Generate the correction report from recorded checks and typesetting metadata."""
from pathlib import Path
from decimal import Decimal,ROUND_HALF_EVEN
import csv,json
HERE=Path(__file__).resolve().parent;PAPER=HERE.parent;ROOT=PAPER.parent

def main():
    v=json.loads((HERE/'fix-pass-validation.json').read_text());facts=json.loads((HERE/'fix-verifications.json').read_text())
    locs=json.loads((HERE/'fix-locations.json').read_text());baseline=json.loads((HERE/'fix-baseline-locations.json').read_text())
    trace=json.loads((HERE/'number-trace.json').read_text());changes=json.loads((HERE/'formatting-changes.json').read_text())
    def sub(slug):
        p=locs['sections']['subapp:'+slug]['page'];return 'p. '+str(p)
    def tab(key):
        r=locs['tables']['tab:'+key]['after'];return f"Table {r['number']} (p. {r['page']})"
    lines=['# Appendix correction pass','',f"Baseline: `{v['baseline_commit']}`. The main paper and references extract identically to the baseline PDF. Pages 1–4 also render pixel-identically. The main paper plus references remains **five pages**, with references ending on shared page 5.",'',f"The complete PDF changed from **37 to {v['new_pdf_pages']} pages**. The appendices changed from **33 to {v['new_pdf_pages']-4} pages**, including shared page 5. There are **107 appendix tables**, down from 135, and **1,959 traced result cells**. The PDF is **{(PAPER/'main.pdf').stat().st_size:,} bytes**.",'',f"PDF SHA-256: `{v['pdf_sha256']}`.",'','## Fixes and locations','','Locations name the original appendix/subsection or original table/listing. Every table mapping, including removed tables, is also recorded in `fix-locations.json`. All table, figure and listing references in the paper use LaTeX cross-references.','', '| Item | Original location | Revised location and change |','| --- | --- | --- |']
    fixes=[
    ('A1','F, Study 1 pilots','study-1-pilots-and-the-one-design-amendment','Removed the calendar date from the amendment sentence.'),
    ('A2','E, Study 2 outcome/regression','study-2-outcome-and-regression','Named the undisclosed card as the reference category.'),
    ('A3','E opening','study-1-estimating-a-card-contrast','Expanded sign conventions to transfers, offers, responder minimums, stated expectations and buyer share; the paragraph precedes this subsection.'),
    ('A4','D, Transcript/action rules','transcript-and-action-rules','Replaced the local-rule wording with the registered rule and the verified zero-mismatch statement.'),
    ('A5','E, Numerical tolerance/reporting','numerical-tolerance-and-reporting','Defined the 29-test Bonferroni family explicitly.'),
    ('B1','F, Study 2 after lock','study-2-after-its-lock','Used the requested two-paragraph explanation of execution, provenance, drift, attempts and resumption.'),
    ('B2','F, Smoke checks/blind pilot','study-2-smoke-checks-and-blind-pilot','Explained smoke tests and forced-position probes, rate limiting and missing cache fields; used the verified Gemini wording and a figure cross-reference.'),
    ('B3','F, Study 1 pilots/after lock','study-1-after-its-lock','Applied all four replacements about the design change, separately stored pilot results, recovery and registration push.'),
    ('B4','D, Role prompts','role-prompts-card-and-turn-instructions','Explained single-pass placeholder substitution.'),
    ('B5','C, Comprehension/design','comprehension-check-and-design-counts','Spelled out the wording/name allocation and the three joint-allocation rows.'),
    ('B6','B, Settings and old Tables 4–5','reported-reasoning-and-cache-usage','Removed the opening filler sentence; clarified Moonshot SDK/address and historical settings; expanded OpenAI/Gemini caching cells and prose. Settings remain Tables 3–6, before this subsection.'),
    ('B7','E, Bootstrap and S1 adjustment','s1-offers-adjusted-for-stated-expectations','Applied the requested plain-language Freedman–Lane and count-matched-rank explanations.'),
    ('B8','H opening','primary-buyer-specific-and-secondary-contrasts','Stated that all 960 main episodes were rebuilt from turns and checked against their summaries.'),
    ('B9','G/H figure introductions','registered-study-1-figures','Named the asset manifest, unchanged plotted data and larger lettering; used figure references throughout G and H.'),
    ('C1','Old Table 37, Terra p-value','registered-study-1-figures','Applied the four-decimal rule with the six-decimal exception; the exact cell is listed below.'),
    ('C2','G/H introductions','primary-equivalence-result','Added the minimum-permutation-p explanation to both introductions.'),
    ('C3','Old Tables 34, 38, 46 and 51','primary-equivalence-result','Used Decimal and round-half-to-even with exact unadjusted pooled lattice values; stated the scope and rule in G.'),
    ('C4','Old Tables 124, 127, 130 and 133','pair-and-condition-descriptives','Displayed all 48 per-pair Length means to two exact decimals.'),
    ('C5','Old Tables 72–83','descriptive-statistics','Ordered all 12 tables as Own model, Other lab, Fictional, Undisclosed, Human.'),
    ('D1','C/D inline literals, old pp. 10/12','transcript-and-action-rules',f"Preserved literal spaces, straight apostrophes and complete agent labels; all {v['inline_literal_occurrences_checked']} inline-literal occurrences match the PDF."),
    ('D2','Old Listings 8, 11, 15, 22, 27, 31 and 37','system-prompts-and-decision-bodies','Made all 37 listings native unbreakable ruled floats; long JSON reply listings span both columns. Full listing locations are listed below.'),
    ('D3','C wrapping explanation and old Listing 37','transcript-and-action-rules','Marked automatic soft wraps with a grey arrow; retained source bytes and hard breaks; the transcript format spans both columns and price: $X stays on one line.'),
    ('D4','B model IDs and Gemini endpoint','reported-reasoning-and-cache-usage','Kept model IDs unbroken and moved full API addresses to their own unbroken lines above the settings tables.'),
    ('E1','A opening','frozen-versions','Deleted the two reviewer/workflow notes before Frozen versions.'),
    ('E2','A/E/F, defensive phrasing','study-1-after-its-lock','Removed or rewrote the specified denials while retaining causal and scoring qualifications that prevent real misreadings.'),
    ('E3','C/D listing lead-ins','system-prompts-and-decision-bodies','Removed the three system and nine decision-body repetitions; one sentence per wording points to its listings; card insertion is explained in the C paragraph.'),
    ('E4','A/F/G/H workflow terms','study-2-after-its-lock','Replaced the specified workflow vocabulary and checked every requested leftover phrase in the PDF.'),
    ('E5','All Saved result/Saved value headings','primary-buyer-specific-and-secondary-contrasts','Changed these headings to Value throughout the tables.'),
    ('E6','Pilot, contrast and coefficient-change captions','s1-coefficient-changes-and-diagnostics','Moved the specified boilerplate into section introductions; retained the special pooled-P1 note.'),
    ('F1','Old Tables 105–112','eligibility-and-permutation-strata',tab('s2-eligibility')+' combines eight outcomes; build assertions verify equality across all six condition/label groups for every outcome.'),
    ('F2','Old Tables 113–116','eligibility-and-permutation-strata',tab('s2-strata')+' contains all 14 permutation tests.'),
    ('F3','Old Tables 117–123','mandate-compliance',tab('s2-mandates')+' has all three original conditions and four buyer models; n is explicitly defined as retained episodes.'),
    ('F4','Old Tables 125/126/128/129/131/132/134/135','pair-and-condition-descriptives','Replaced eight count tables with a generated sentence whose 48 identical cells are asserted in code. Retained the four share/Length tables.'),
    ('F5','Old Tables 84–87','final-prompt-comprehension-check','Removed the four duplicate tables after verifying all 16 model/card count rows against the registered Figure 5; the text points to that figure.')]
    for ident,old,slug,change in fixes:lines.append(f'| {ident} | {old} | {sub(slug)}. {change} |')
    lines += ['','## Verification results','', '- **A4:** all eight Study 2 model/role rows report zero acceptance-price mismatches. The episode and per-call tables also contain only false mismatch flags.', '- **A5:** the divisor counts exactly 29 pooled secondary Study 1 permutation tests: 17 unadjusted outcomes, 6 stated-belief contrasts and 6 belief-adjusted offers. It excludes the primary dictator contrast, all model-specific tests and all Study 2 tests.', '- **B1:** the runner compares returned and expected model strings and halts dispatch on a difference. The locked pilot strings equal the requested API IDs. The approved launcher requires completion of all 960 episodes, preserves four attempts per response opportunity and has no aggregate attempt cap. Its frozen execution revision is `4e088670c0cc8386eccf8fff01d93d353a230bda`.', '- **B2:** 35 pilot episodes involved Gemini; their maximum length was 11 messages. Thus no episode involving Gemini reached message 12. This is stronger than merely saying Gemini was never the final mover. The pilot had the recorded one Kimi HTTP 429 retry and no model-string change.', '- **B4:** `render_template` uses one `re.sub` pass over the original template. Its callback inserts message text without rescanning the replacement.', '- **B5:** the configured wording and other-name margins are both 7/7/6, with rows (3,2,2), (2,3,2), (2,2,2).', '- **F1–F5:** equality/count assertions and the registered-figure comparison run during table generation and fail if the conditions cease to hold. Their source rows are retained in the generated-statement trace.', '', '### P-value display change','']
    pchanges=[c for c in changes if c['field'].startswith('permutation_p')]
    assert len(pchanges)==1
    c=pchanges[0];lines += [f"Exactly one cell changed: {tab(c['table_key'])}, GPT-6.1 Terra, proposer other-lab minus undisclosed. CSV row {c['row']} has raw p = {c['raw']}; its display changed from {c['previous_displays'][0]} to **{c['display']}**. All appendix p-value fields were checked by the shared formatter.",'','### Exact cent ties','', 'The rule is **round half to even**. Unadjusted pooled Study 1 estimates and their bootstrap endpoints are recovered as integer/240 values within the CSV export precision, then formatted with Decimal. The lattice claim is deliberately scoped to unadjusted contrasts: belief-adjusted regression coefficients are not generally multiples of 1/240. Other values use their exact exported decimal strings. Per-pair Length means are recovered at denominator 20.','', '**No existing displayed cent value changes under this rule.** The preceding appendix already displayed the verified ties using the same half-even direction. Exact lattice recovery now makes that choice explicit and reproducible. The main paper remains unchanged at $4.18, and Appendix G remains $4.18. All twelve cent-tie fields checked are listed here; this includes the five cells specifically identified in the request.','', '| Table | Source CSV row/field | Exact tie | Display |','| --- | --- | --- | --- |']
    cells={(str(c['row']),c['field']):c for c in trace['numeric_cells'] if c['source']=='results/study1/generated/contrasts.csv'}
    for tie in facts['C3']['verified_ties']:
        c=cells[str(tie['csv_row']),tie['field']]
        lines.append(f"| {tab(c['table_key'])} | {tie['csv_row']} / {tie['field']} | {tie['exact_decimal']} | {c['display']} |")
    lines += ['','### Every Length display change','', 'All 48 display strings changed from one to two decimal places, including added trailing zeroes. No underlying mean changed. The original tables 124, 127, 130 and 133 are now '+', '.join(tab('s2-pair-outcomes-'+m) for m in ['claude_sonnet_5_5','gpt_6_1_terra','gemini_4_hydrogen','kimi_k3_1_pro'])+'.','', '| Buyer | Seller | Original condition | Before | After |','| --- | --- | --- | --- | --- |']
    rows=list(csv.DictReader((ROOT/'results/study2/main/tables/pair_condition_descriptives.csv').open()))
    short={'claude_sonnet_5_5':'Sonnet','gpt_6_1_terra':'Terra','gemini_4_hydrogen':'Hydrogen','kimi_k3_1_pro':'Kimi'}
    for c in changes:
        if c['field']!='messages_used_mean_retained':continue
        r=rows[c['row']-2];b,s=r['pair_id'].split('__')
        lines.append(f"| {short[b]} | {short[s]} | {r['condition']} | {c['previous_displays'][0]} | {c['display']} |")
    lines += ['','## Listing locations','', 'Listing numbers are retained. Each caption and complete body is in one float. Listings 24, 25 and 37 span both columns. Original hard line breaks are retained; only automatic continuations receive the grey arrow. All 29 source/template blocks reconstruct byte for byte.','', '| Listing | Original page | New page | Source label |','| --- | --- | --- | --- |']
    for label,r in sorted(locs['listings'].items(),key=lambda x:int(x[1]['number'])):
        lines.append(f"| {r['number']} | {baseline['listing_pages_by_number'].get(r['number'],'see original PDF')} | {r['page']} | {label} |")
    lines += ['','## Build, preservation and remaining limitation','', '- PDFLaTeX and BibTeX build passed, with zero errors, zero overfull boxes and zero undefined references/citations. All 15 fonts are embedded Type 1; no Type 3, CID or Identity-H fonts occur. Ordinary underfull-box messages remain.', '- The official kit files and the eight appendix figure assets are unchanged. No forbidden package, page-break command, smaller type, margin change or float-spacing override was added.', '- Main PDF text through the last reference is identical to the previous PDF; the main source, draft, bibliography and Figure 1 are byte-identical. Study code, prompts, configurations, logs, results, pre-registrations and protected tags were not modified.', f"- All requested leftover phrases are absent. All {v['inline_literal_occurrences_checked']} inline-literal occurrences match, including spaces and apostrophes. Listing 37 keeps the complete price: $X phrase on one line.", '- Every appendix page was inspected as an image. No split listing, separated caption, clipped table/figure, overlap or missing glyph was found.', '- **G6 spacing limitation:** some native float/column gaps remain, especially on prompt-only and final float pages. The requirement to eliminate every large gap is not fully met. Trials with larger grouped floats and unbreakable inline boxes worsened the layout; the final version retains ruled floats and the kit spacing. No manual page breaks or spacing overrides were used to conceal the remaining white space.', '- **C3 wording qualification:** the 1/240 statement applies to unadjusted pooled contrasts and endpoints, not belief-adjusted regression coefficients. No fact check contradicted the other requested replacements.', '', 'The full machine checks are in `fix-verifications.json`, `fix-pass-validation.json`, `number-trace.json`, `formatting-changes.json`, `fix-locations.json` and the two general validation files. No analysis or model API call was run. The correction pass is for a paper-only local commit; nothing is pushed.','']
    (HERE/'fix-pass-report.md').write_text('\n'.join(lines))
if __name__=='__main__':main()
